def normalize_sr(val):
    """Normalize SR to percentage (0-100 scale)"""
    if val is None:
        return None
    if isinstance(val, str):
        # Handle "79.5" or "0.79" or "79.0% (79/100)"
        val = val.split('%')[0].split('(')[0].strip()
        try:
            val = float(val)
        except:
            return None
    if isinstance(val, (int, float)):
        if val <= 1.0:
            return round(val * 100, 1)
        return round(val, 1)
    return None

def get_sr(exp):
    metrics = exp.get("metrics", {}) or {}
    for k in ["SR", "success_rate", "overall_sr", "overall_success_rate", "avg_success_rate"]:
        if k in metrics:
            return normalize_sr(metrics[k])
    return None

# Build grid by scanning eval-supp-* experiments (the canonical Table 1 runs)
grid = {}  # (suite, method, seed) -> (exp_id, sr)

for exp_id, exp in experiments.items():
    status = exp.get("status", "")
    conclusion = exp.get("conclusion", "")
    if status != "DONE":
        continue
    # Only consider success or negative with valid SR
    if conclusion not in ("success", "negative", "killed"):
        continue

    eid = exp_id.lower()
    sr = get_sr(exp)

    # Match suite
    suite = None
    # Handle "obj" abbreviation
    if "long" in eid:
        suite = "long"
    elif "spatial" in eid:
        suite = "spatial"
    elif "goal" in eid:
        suite = "goal"
    elif "object" in eid or "obj" in eid:
        suite = "object"

    if suite is None:
        continue

    # Match seed
    seed = None
    for s in seeds:
        if f"s{s}" in eid or f"seed{s}" in eid:
            seed = s
            break
    if seed is None:
        continue

    # Match method - focus on eval-supp-* pattern
    method = None

    if "vla-only" in eid or "vla_only" in eid:
        # Exclude reconvla, k2mean, crm, adaptive
        if not any(x in eid for x in ["reconvla", "k2mean", "crm", "adapt"]):
            method = "vla_only"
    elif "crm" in eid and ("norm005" in eid or "crm005" in eid):
        method = "crm_norm005"
    elif "reconvla" in eid:
        method = "reconvla"
    elif "adapt" in eid and "tau025" in eid:
        method = "adapt_tau025"
    elif "k2mean" in eid:
        method = "k2mean"

    if method is None:
        continue

    key = (suite, method, seed)

    # Prefer success over negative, and prefer experiments with SR
    if key in grid:
        existing = grid[key]
        # If existing is success with SR, keep it unless new one is also success with SR and from eval-supp
        if existing[2] == "success" and existing[1] is not None:
            if conclusion == "success" and sr is not None and "eval-supp" in eid and "eval-supp" not in existing[0]:
                grid[key] = (exp_id, sr, conclusion)
            continue
        if sr is not None and (conclusion == "success" or existing[1] is None):
            grid[key] = (exp_id, sr, conclusion)
    else:
        if conclusion != "killed" or sr is not None:  # Skip killed without SR
            grid[key] = (exp_id, sr, conclusion)

# Print grid
method_labels = {
    "vla_only": "VLA-only (K=1)",
    "crm_norm005": "CRM (norm=0.05, K=10)", 
    "reconvla": "ReconVLA (K=10)",
    "adapt_tau025": "ACR (τ=0.25, K=2)",
    "k2mean": "K2-mean (K=2)",
